import unicodedata


def _char_width(ch: str) -> int:
    cat = unicodedata.category(ch)
    if cat in ("Mn", "Me", "Cf"):
        return 0
    if unicodedata.east_asian_width(ch) in ("W", "F"):
        return 2
    return 1


def fit(text: str, width: int) -> str:
    total = 0
    for ch in text:
        total += _char_width(ch)
    if total <= width:
        return text

    budget = width - 1  # reserve one column for the ellipsis
    used = 0
    end = 0
    for i, ch in enumerate(text):
        w = _char_width(ch)
        if w == 0:
            # Zero-width characters stay with the preceding base character
            # (or at the start of the text); include them only if their
            # base was included, which is guaranteed since we stop at bases.
            end = i + 1
            continue
        if used + w > budget:
            break
        used += w
        end = i + 1
    return text[:end] + "…"
